// Política de noticias, compartida por radar, guion, producción y publicación.
function fechaNoticia(fecha) {
  const ms = Date.parse(fecha);
  const dia = x => new Intl.DateTimeFormat('en-CA', { timeZone:'America/Lima', year:'numeric', month:'2-digit', day:'2-digit' }).format(x);
  return Number.isFinite(ms) && ms <= Date.now() && dia(ms) === dia(Date.now());
}
function validarHechos(hechos, consultadas) {
  const urls = new Set(consultadas || []);
  return Array.isArray(hechos) && hechos.length > 0 && hechos.length <= 30 &&
    new Set(hechos.map(h => h.id)).size === hechos.length && hechos.every(h =>
      typeof h.id === 'string' && /^[a-z0-9_-]{1,40}$/.test(h.id) && typeof h.dato === 'string' && h.dato.trim() &&
      Array.isArray(h.fuentes) && h.fuentes.length > 0 && h.fuentes.every(f =>
        typeof f.url === 'string' && /^https:\/\/[a-z0-9.-]+(?::443)?(?:[/?#][^\s]*)?$/i.test(f.url) &&
        urls.has(f.url) && typeof f.titulo === 'string' && f.titulo.trim() && Number.isFinite(Date.parse(f.fecha)) && Date.parse(f.fecha) <= Date.now()));
}
function validarNoticia(n) {
  if (!n || !fechaNoticia(n.fecha) || !n.titulo?.trim() || !validarHechos(n.hechos, n.fuentes_consultadas))
    throw new Error('Noticia detenida: faltan hechos, fuentes consultadas o noticia del día');
  return n;
}
function validarVerificacion(n, r, respuesta) {
  validarNoticia(n);
  if (!respuesta?.busqueda_real || r?.verificado !== true || !validarHechos(r.hechos, respuesta.fuentes_consultadas) ||
      r.hechos.length !== n.hechos.length || n.hechos.some(h => !r.hechos.some(v => v.id === h.id && v.dato === h.dato && v.estado === 'ok')))
    throw new Error('Noticia detenida: datos sin verificar o contradictorios');
  return { ...n, hechos:r.hechos, fuentes_consultadas:respuesta.fuentes_consultadas, verificado:true, verificado_en:new Date().toISOString() };
}
function exigirNoticia(n) {
  validarNoticia(n);
  const age = Date.now() - Date.parse(n.verificado_en);
  if (n.verificado !== true || !Number.isFinite(age) || age < 0 || age > 24 * 3600000 || n.hechos.some(h => h.estado !== 'ok'))
    throw new Error('Noticia detenida: verificación ausente o vencida');
}
function huellaGuion(g) {
  return require('crypto').createHash('sha256').update(JSON.stringify(g)).digest('hex');
}
function exigirGuion(v, g) {
  if (!v.modo_noticia) return;
  const n = JSON.parse(v.noticia || 'null'); exigirNoticia(n);
  if (!v.noticia_guion_hash || (g && v.noticia_guion_hash !== huellaGuion(g)))
    throw new Error('Noticia detenida: el guion no coincide con la versión verificada');
}
function exigirVisuales(storyboard) {
  const planos = storyboard?.planos;
  if (!Array.isArray(planos) || !planos.length || planos.some(p =>
    !['imagen','clip'].includes(p.tipo) || p.origen_visual !== 'generado' ||
    !['mapa','cifra','esquema'].includes(p.recurso_didactico) ||
    typeof p.prompt_imagen !== 'string' || !p.prompt_imagen.trim() ||
    /https?:\/\//i.test(JSON.stringify(p))))
    throw new Error('Noticia detenida: solo mapas, cifras y esquemas generados; nunca imágenes de medios');
}
function exigirStoryboard(v, storyboard) {
  if (!v.modo_noticia) return;
  exigirGuion(v, null);
  exigirVisuales(storyboard);
  if (!v.noticia_storyboard_hash || v.noticia_storyboard_hash !== huellaGuion(storyboard))
    throw new Error('Noticia detenida: storyboard distinto de la versión verificada');
}

const v=$('Noticia · Subir a redes video').first().json; if (!v.video_id) throw new Error('Video no encontrado'); exigirGuion(v,null); if (v.modo_noticia && !v.noticia_storyboard_hash) throw new Error('Noticia sin storyboard verificado'); return $('Noticia · Subir a redes entrada').all();

// Política pura de transporte. No envía solicitudes ni conserva errores de proveedores.
function evaluarRespuestaFiable(r, intento, ahora = Date.now(), azar = Math.random()) {
  if (!Number.isInteger(intento) || intento < 1 || intento > 4) throw new Error('Intento de transporte inválido');
  const recibido = Number(r?.statusCode || r?.error?.statusCode || r?.error?.httpCode || 0);
  const codigo = Number.isInteger(recibido) ? recibido : 0;
  if (codigo >= 200 && codigo < 300) return { reintentar: false, esperaSegundos: 0, respuesta: r.body, codigo };
  const transitorio = [408, 425, 429].includes(codigo) || (codigo >= 500 && codigo <= 599) || (!codigo && !!r?.error);
  if (!transitorio) throw new Error('Respuesta HTTP no recuperable; revisar la incidencia sin reenviar la operación');
  if (intento === 4) throw new Error('Transporte agotado tras cuatro intentos seguros; requiere conciliación');
  const headers = r.headers || r.error?.headers || {};
  const raw = Object.entries(headers).find(([k]) => k.toLowerCase() === 'retry-after')?.[1];
  let retryAfter = 0;
  if (raw !== undefined) {
    const texto = String(raw).trim();
    if (/^\d+(?:\.\d+)?$/.test(texto)) retryAfter = Math.ceil(Number(texto));
    else {
      // Date.parse admite basura como "-1" o fechas abreviadas: aceptar solo
      // IMF-fixdate y exigir que la fecha y el día de semana sean coherentes.
      const instante = Date.parse(texto);
      if (!/^(Mon|Tue|Wed|Thu|Fri|Sat|Sun), \d{2} (Jan|Feb|Mar|Apr|May|Jun|Jul|Aug|Sep|Oct|Nov|Dec) \d{4} \d{2}:\d{2}:\d{2} GMT$/.test(texto) || !Number.isFinite(instante) || new Date(instante).toUTCString() !== texto) {
        throw new Error('Retry-After inválido; detener antes de incumplir la cuota');
      }
      retryAfter = Math.max(0, Math.ceil((instante - ahora) / 1000));
    }
    if (!Number.isFinite(retryAfter)) throw new Error('Retry-After inválido; detener antes de incumplir la cuota');
    // El callback firmado caduca: no esperar indefinidamente ni anticipar Retry-After.
    if (retryAfter > 60) throw new Error('Retry-After excede el presupuesto; reanudar tras conciliación');
  }
  const base = [2, 8, 32][intento - 1];
  const jitter = Math.min(2, Math.max(0, Math.floor(Number(azar) * 3) || 0));
  return { reintentar: true, esperaSegundos: Math.max(base + jitter, retryAfter), respuesta: null, codigo };
}

function clavePublicacionFiable(video, tipo, red) {
  if (!video || !tipo || !red) throw new Error('Publicación sin identidad estable');
  return 'publicacion:v1:' + require('crypto').createHash('sha256').update(JSON.stringify([String(video), String(tipo), String(red)])).digest('hex');
}

function publicacionYaReservada(video, tipo, red, publicaciones, reservas) {
  const clave = clavePublicacionFiable(video, tipo, red);
  return reservas.some(r => r.evento === clave) || publicaciones.some(p => p.video_id === video && p.tipo === tipo && String(p.plataformas || '').split(',').includes(red));
}

function elegirReservasPublicacion(pedidos, propias, reservas) {
  const vistas = new Set();
  return pedidos.filter(p => {
    const clave = p.clave_publicacion;
    if (!clave || vistas.has(clave)) return false;
    vistas.add(clave);
    const mia = propias.filter(r => r.evento === clave);
    const todas = reservas.filter(r => r.evento === clave);
    if (mia.length !== 1 || !todas.length || [...mia, ...todas].some(r => !Number.isSafeInteger(Number(r.id)) || Number(r.id) <= 0)) {
      throw new Error('No se pudo verificar la reserva de publicación; no reenviar');
    }
    const id = Number(mia[0].id);
    if (!todas.some(r => Number(r.id) === id)) throw new Error('La reserva aún no es visible; no reenviar');
    return id === Math.min(...todas.map(r => Number(r.id)));
  });
}

